SELECT tenant_id AS tenantId,relation_id AS relationId,campaign_id AS campaignId,organization_id AS organizationId,shop_id AS shopId,
  participant_id AS participantId,token_id AS tokenId,definition_id AS definitionId,definition_version AS definitionVersion,generation,
  artifact_id AS artifactId,policy_hash AS policyHash,bound_at AS boundAt,deadline_at AS qualifyDeadline,consent_version AS consentVersion,consent_hash AS consentHash,state
FROM mk_referral_relation WHERE tenant_id=#{tenant}
AND relation_id=#{relationId}AND campaign_id=#{campaign} AND invitee_key=#{invitee}
FOR UPDATE
